/**
 * Prepaid backup capacity for one region, sold by Compute and bought for a term through its own Billing subscription. Compute applies its coverage to backup usage; it is not a Billing allowance or credit.
 */
export interface BackupCapacityPack {
  id: string;
  region_id: string;
  /** @minimum 1 */
  capacity_gib: number;
  /** `pending` awaits acceptance of its order; `provisioning` is being applied; `active` covers backup capacity; `ended` no longer does because its subscription has ended; `failed` means the purchase failed, as `failure_reason` states. */
  status: BackupCapacityPackStatus;
  /**
   * Why the purchase failed; null unless `status` is `failed`. `provisioning_failed` means it failed after the order was accepted, and its charge is refunded.
   * @nullable
   */
  failure_reason: BackupCapacityPackFailureReason;
  order_id: string;
  /**
   * The pack's Billing subscription, through which it is renewed or canceled.
   * @nullable
   */
  subscription_id: string | null;
  /** The subscription a cancellation through Billing has to cover to release this capacity pack. A subscription that has ended is not listed, and the list is empty when no subscription pays for the pack. */
  release_subscription_ids: string[];
  created_at: string;
}

export interface BackupCapacityPackListResponseBody {
  items: BackupCapacityPack[];
  pagination: OffsetPagination;
}

